    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m, n;
    cin >> m >> n;
    vector<vector<long long>> g = spiralFibonacci(m, n);
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) cout << g[i][j] << (j + 1 < n ? ' ' : '\n');
