import java.util.*;
import java.io.*;

public class Main {
    static long[][] spiralFibonacci(int m, int n) {
        // Write your solution here
        return new long[m][n];
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        int n = sc.nextInt();
        long[][] g = spiralFibonacci(m, n);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) sb.append(g[i][j]).append(j + 1 < n ? " " : "\n");
        }
        System.out.print(sb);
    }
}
